export interface CalendarBooking {
  id: string
  scheduled_at: string
  end_at: string
  duration_min: number
  status: string
  client: { id: string; first_name: string; last_name: string | null }
  artist: { id: string; display_name: string; avatar_url: string | null; sort_order: number }
  service: { id: string; name: string; color: string | null } | null
}

interface CalendarViewProps {
  bookings: CalendarBooking[]
  isLoading: boolean
  error: string | null
  totalBookings: number
  filterArtistIds: string[]
  filterStatuses: string[]
  filterServiceIds: string[]
  onArtistFilterChange: (ids: string[]) => void
  onStatusFilterChange: (statuses: string[]) => void
  onServiceFilterChange: (ids: string[]) => void
  onNewAppointment: (start?: Date, end?: Date) => void
  onEditAppointment: (id: string) => void
  onReschedule: (id: string, newStart: Date, newEnd: Date) => Promise<void>
  onRetry: () => void
  studioId?: string
}

// Minimum default slot duration when clicking an empty slot (30 min)
const DEFAULT_SLOT_DURATION_MS = 30 * 60 * 1000

// Mobile breakpoint — mirrors Tailwind md (768px)
const MOBILE_BREAKPOINT = 768

function getDefaultMobileView(): CalendarViewType {
  if (typeof window === 'undefined') return 'timeGridWeek'
  return window.innerWidth < MOBILE_BREAKPOINT ? 'listWeek' : 'timeGridWeek'
}

export function CalendarView({
  bookings,
  isLoading,
  error,
  totalBookings,
  filterArtistIds,
  filterStatuses,
  filterServiceIds,
  onArtistFilterChange,
  onStatusFilterChange,
  onServiceFilterChange,
  onNewAppointment,
  onEditAppointment,
  onReschedule,
  onRetry,
  studioId,
}: CalendarViewProps) {
  const calendarRef = useRef<FullCalendar>(null)
  const containerRef = useRef<HTMLDivElement>(null)

  // Pointer tracking for mobile swipe (C6)
  const swipeStartX = useRef<number | null>(null)
  const swipeStartY = useRef<number | null>(null)

  const [view, setView] = useState<CalendarViewType>(() => {
    if (typeof window !== 'undefined') {
      const saved = localStorage.getItem('inkos-calendar-view')
      if (saved) return saved as CalendarViewType
    }
    return getDefaultMobileView()
  })
  const [title, setTitle] = useState('')

  // Derive range dates for iCal export
  const [rangeStart, setRangeStart] = useState<string | undefined>()
  const [rangeEnd, setRangeEnd] = useState<string | undefined>()

  // Sync view to FullCalendar on change
  useEffect(() => {
    const api = calendarRef.current?.getApi()
    if (!api) return
    api.changeView(view)
    localStorage.setItem('inkos-calendar-view', view)
  }, [view])

  // Update title after navigation
  const updateTitle = useCallback(() => {
    const api = calendarRef.current?.getApi()
    if (!api) return
    setTitle(api.view.title)
    const range = api.view.currentRange
    setRangeStart(range.start.toISOString())
    setRangeEnd(range.end.toISOString())
  }, [])

  useEffect(() => {
    const api = calendarRef.current?.getApi()
    if (api) {
      startTransition(() => {
        setTitle(api.view.title)
        const range = api.view.currentRange
        setRangeStart(range.start.toISOString())
        setRangeEnd(range.end.toISOString())
      })
    }
  }, [])

  // ── C5: Keyboard shortcuts ──────────────────────────────────────────────
  useEffect(() => {
    function onKeyDown(e: KeyboardEvent) {
      // Ignore when typing in inputs/textareas/contenteditable
      const target = e.target as HTMLElement
      const tag = target.tagName
      if (tag === 'INPUT' || tag === 'TEXTAREA' || target.isContentEditable) return
      // Ignore modifier combos
      if (e.ctrlKey || e.metaKey || e.altKey) return

      const api = calendarRef.current?.getApi()
      if (!api) return

      switch (e.key) {
        case 't':
        case 'T':
          e.preventDefault()
          api.today()
          updateTitle()
          break
        case '[':
          e.preventDefault()
          api.prev()
          updateTitle()
          break
        case ']':
          e.preventDefault()
          api.next()
          updateTitle()
          break
        case 'd':
        case 'D':
          e.preventDefault()
          setView('timeGridDay')
          break
        case 'w':
        case 'W':
          e.preventDefault()
          setView('timeGridWeek')
          break
        case 'm':
        case 'M':
          e.preventDefault()
          setView('dayGridMonth')
          break
        case 'a':
        case 'A':
          e.preventDefault()
          setView('listWeek')
          break
        case 'n':
        case 'N':
          e.preventDefault()
          onNewAppointment()
          break
        case 'Escape':
          // Propagates naturally; no override needed here
          break
        default:
          break
      }
    }

    window.addEventListener('keydown', onKeyDown)
    return () => window.removeEventListener('keydown', onKeyDown)
  }, [onNewAppointment, updateTitle])

  // ── C6: Mobile swipe gesture ────────────────────────────────────────────
  useEffect(() => {
    const el = containerRef.current
    if (!el) return

    function onPointerDown(e: PointerEvent) {
      swipeStartX.current = e.clientX
      swipeStartY.current = e.clientY
    }

    function onPointerUp(e: PointerEvent) {
      if (swipeStartX.current === null || swipeStartY.current === null) return
      const dx = e.clientX - swipeStartX.current
      const dy = e.clientY - swipeStartY.current
      swipeStartX.current = null
      swipeStartY.current = null

      // Only horizontal swipes (dx > 50, horizontal dominates)
      if (Math.abs(dx) < 50 || Math.abs(dy) > Math.abs(dx)) return

      const api = calendarRef.current?.getApi()
      if (!api) return

      if (dx < 0) {
        api.next()
      } else {
        api.prev()
      }
      updateTitle()
    }

    el.addEventListener('pointerdown', onPointerDown)
    el.addEventListener('pointerup', onPointerUp)
    return () => {
      el.removeEventListener('pointerdown', onPointerDown)
      el.removeEventListener('pointerup', onPointerUp)
    }
  }, [updateTitle])

  const events: EventInput[] = useMemo(() => {
    return bookings
      .filter((b) => {
        if (filterArtistIds.length > 0 && !filterArtistIds.includes(b.artist.id)) return false
        if (filterStatuses.length > 0 && !filterStatuses.includes(b.status)) return false
        if (filterServiceIds.length > 0 && (b.service === null || !filterServiceIds.includes(b.service.id))) return false
        return true
      })
      .map((b) => ({
        id: b.id,
        title: `${b.client.first_name} ${b.client.last_name ?? ''}`.trim(),
        start: b.scheduled_at,
        end: b.end_at,
        classNames: [
          getArtistColorClass(b.artist.sort_order),
          `status-${b.status}`,
        ],
        extendedProps: {
          appointmentId: b.id,
          artistId: b.artist.id,
          status: b.status,
          serviceName: b.service?.name ?? null,
        },
      }))
  }, [bookings, filterArtistIds, filterStatuses, filterServiceIds])

  const artists = useMemo(() => {
    const seen = new Set<string>()
    return bookings
      .filter((b) => {
        if (seen.has(b.artist.id)) return false
        seen.add(b.artist.id)
        return true
      })
      .map((b) => ({
        id: b.artist.id,
        display_name: b.artist.display_name,
        sort_order: b.artist.sort_order,
        colorClass: getArtistColorClass(b.artist.sort_order),
      }))
  }, [bookings])

  const services = useMemo(() => {
    const seen = new Set<string>()
    return bookings
      .filter((b) => {
        if (!b.service) return false
        if (seen.has(b.service.id)) return false
        seen.add(b.service.id)
        return true
      })
      .map((b) => ({
        id: b.service!.id,
        name: b.service!.name,
      }))
  }, [bookings])

  // ── C3: Drag-to-reschedule with optimistic rollback + undo ──────────────
  const handleEventDrop = useCallback(
    async (info: EventDropArg) => {
      const { event, revert } = info
      if (!event.start || !event.end) return

      // Capture pre-drop state for undo
      const originalStart = new Date(event.start.getTime() - (info.delta?.milliseconds ?? 0))
      const originalEnd = new Date(event.end.getTime() - (info.delta?.milliseconds ?? 0))
      const appointmentId = event.id

      let undoUsed = false

      // Show optimistic undo toast
      toast.success('Appointment rescheduled', {
        action: {
          label: 'Undo',
          onClick: () => {
            undoUsed = true
            revert()
            // Fire API call to restore original times
            onReschedule(appointmentId, originalStart, originalEnd).catch((err) => {
              logger.error({ err }, 'undo reschedule failed')
              toast.error('Failed to undo reschedule')
            })
          },
        },
        duration: 6000,
      })

      try {
        await onReschedule(appointmentId, event.start, event.end)
      } catch (err) {
        if (undoUsed) return // Undo already in flight, ignore
        const message = err instanceof Error ? err.message : 'Reschedule failed'
        if (message.includes('time_slot_unavailable') || message.includes('23P01')) {
          toast.error('That time slot is already booked')
        } else {
          toast.error('Failed to reschedule appointment')
        }
        revert()
        logger.error({ err }, 'calendar event drop failed')
      }
    },
    [onReschedule]
  )

  const handleEventResize = useCallback(
    async (info: EventResizeDoneArg) => {
      const { event, revert } = info
      if (!event.start || !event.end) return

      try {
        await onReschedule(event.id, event.start, event.end)
        toast.success('Appointment duration updated')
      } catch (err) {
        const message = err instanceof Error ? err.message : 'Resize failed'
        if (message.includes('time_slot_unavailable') || message.includes('23P01')) {
          toast.error('That time slot is already booked')
        } else {
          toast.error('Failed to update appointment duration')
        }
        revert()
        logger.error({ err }, 'calendar event resize failed')
      }
    },
    [onReschedule]
  )

  const handleSelect = useCallback(
    (info: DateSelectArg) => {
      onNewAppointment(info.start, info.end)
    },
    [onNewAppointment]
  )

  // ── C4: Click-empty-slot → quick-add (dateClick) ────────────────────────
  const handleDateClick = useCallback(
    (info: DateClickArg) => {
      const start = info.date
      const end = new Date(start.getTime() + DEFAULT_SLOT_DURATION_MS)
      onNewAppointment(start, end)
    },
    [onNewAppointment]
  )

  const handleEventClick = useCallback(
    (info: EventClickArg) => {
      onEditAppointment(info.event.extendedProps.appointmentId as string)
    },
    [onEditAppointment]
  )

  const filteredCount = events.length
  const isEmpty = !isLoading && filteredCount === 0

  return (
    <div className="flex flex-col flex-1 overflow-hidden" ref={containerRef}>
      <CalendarToolbar
        view={view}
        title={title}
        studioId={studioId}
        rangeStart={rangeStart}
        rangeEnd={rangeEnd}
        onViewChange={setView}
        onPrev={() => {
          calendarRef.current?.getApi().prev()
          updateTitle()
        }}
        onNext={() => {
          calendarRef.current?.getApi().next()
          updateTitle()
        }}
        onToday={() => {
          calendarRef.current?.getApi().today()
          updateTitle()
        }}
        onNewAppointment={() => onNewAppointment()}
      />

      <CalendarFilterRow
        artists={artists}
        services={services}
        filterArtistIds={filterArtistIds}
        filterStatuses={filterStatuses}
        filterServiceIds={filterServiceIds}
        onArtistFilterChange={onArtistFilterChange}
        onStatusFilterChange={onStatusFilterChange}
        onServiceFilterChange={onServiceFilterChange}
      />

      {/* Keyboard shortcut hint bar (desktop only) */}
      <div className="calendar-shortcuts-bar hidden sm:flex">
        {[
          { key: 'T', label: 'Today' },
          { key: '[', label: 'Prev' },
          { key: ']', label: 'Next' },
          { key: 'D', label: 'Day' },
          { key: 'W', label: 'Week' },
          { key: 'M', label: 'Month' },
          { key: 'A', label: 'Agenda' },
          { key: 'N', label: 'New' },
        ].map(({ key, label }) => (
          <span key={key} className="inline-flex items-center gap-1">
            <kbd className="calendar-shortcut-key">{key}</kbd>
            <span>{label}</span>
          </span>
        ))}
      </div>

      {error && (
        <div className="px-4 py-2">
          <Alert variant="destructive">
            <AlertCircle className="h-4 w-4" />
            <AlertDescription className="flex items-center justify-between">
              Couldn&apos;t load appointments
              <Button
                variant="outline"
                size="sm"
                className="ml-3 h-6 text-xs"
                onClick={onRetry}
              >
                Retry
              </Button>
            </AlertDescription>
          </Alert>
        </div>
      )}

      {isLoading && (
        <div className="flex-1 overflow-hidden px-4 pb-4 pt-2">
          <div className="space-y-2">
            <Skeleton className="h-16 w-3/4 rounded-md" />
            <Skeleton className="h-12 w-1/2 rounded-md" />
            <Skeleton className="h-20 w-2/3 rounded-md" />
          </div>
        </div>
      )}

      {!isLoading && isEmpty && totalBookings === 0 && (
        <div className="flex flex-1 flex-col items-center justify-center gap-4 px-4 pb-4">
          <div className="rounded-xl bg-primary/10 p-4">
            <CalendarPlus className="h-12 w-12 text-primary/70" />
          </div>
          <div className="text-center space-y-1">
            <h3 className="text-base font-medium">Your first booking will appear here</h3>
            <p className="text-sm text-muted-foreground">
              Share your booking link to get started
            </p>
          </div>
          <div className="flex gap-2">
            <Button size="sm" onClick={() => onNewAppointment()}>
              <CalendarPlus className="mr-2 h-4 w-4" />
              New booking
            </Button>
          </div>
        </div>
      )}

      {!isLoading && isEmpty && totalBookings > 0 && (
        <div className="flex flex-1 flex-col items-center justify-center gap-4 px-4 pb-4">
          <div className="rounded-xl bg-primary/10 p-4">
            <FilterX className="h-10 w-10 text-primary/70" />
          </div>
          <div className="text-center space-y-1">
            <h3 className="text-base font-medium">No appointments match these filters</h3>
            <p className="text-sm text-muted-foreground">
              Try a different artist, date, or status
            </p>
          </div>
          <Button
            variant="outline"
            size="sm"
            onClick={() => {
              onArtistFilterChange([])
              onStatusFilterChange([])
              onServiceFilterChange([])
            }}
          >
            Clear filters
          </Button>
        </div>
      )}

      {!isLoading && !isEmpty && (
        <div className="flex-1 overflow-hidden px-4 pb-4">
          <div className="h-full rounded-xl border border-border/40 overflow-hidden shadow-[var(--shadow-glow-card,var(--shadow-card))]">
          <FullCalendar
