// ── C7: URL search param helpers ────────────────────────────────────────────
function parseIds(value: string | null): string[] {
  if (!value) return []
  return value.split(',').filter(Boolean)
}

function serializeIds(ids: string[]): string {
  return ids.join(',')
}

export function CalendarPageClient() {
  const router = useRouter()
  const searchParams = useSearchParams()
  const queryClient = useQueryClient()

  // ── C7: Lift filter state into URL ─────────────────────────────────────
  const filterArtistIds = parseIds(searchParams.get('artists'))
  const filterStatuses = parseIds(searchParams.get('statuses'))
  const filterServiceIds = parseIds(searchParams.get('services'))

  function updateFilters(updates: {
    artists?: string[]
    statuses?: string[]
    services?: string[]
  }) {
    const next = new URLSearchParams(searchParams.toString())
    if (updates.artists !== undefined) {
      if (updates.artists.length > 0) {
        next.set('artists', serializeIds(updates.artists))
      } else {
        next.delete('artists')
      }
    }
    if (updates.statuses !== undefined) {
      if (updates.statuses.length > 0) {
        next.set('statuses', serializeIds(updates.statuses))
      } else {
        next.delete('statuses')
      }
    }
    if (updates.services !== undefined) {
      if (updates.services.length > 0) {
        next.set('services', serializeIds(updates.services))
      } else {
        next.delete('services')
      }
    }
    router.replace(`?${next.toString()}`, { scroll: false })
  }

  // ── Drawer state ────────────────────────────────────────────────────────
  const {
    drawerOpen,
    setDrawerOpen,
    editingId,
    defaultStart,
    defaultEnd,
    openNew,
    openEdit,
  } = useCalendarDrawer()

  const {
    data,
    isLoading,
    error,
    refetch,
  } = useQuery<{ data: CalendarBooking[]; count: number }>({
    queryKey: ['bookings', 'calendar'],
    queryFn: async () => {
      const res = await fetch('/api/bookings?per_page=500')
      if (!res.ok) throw new Error('Failed to fetch bookings')
      return res.json() as Promise<{ data: CalendarBooking[]; count: number }>
    },
  })

  const rescheduleMutation = useMutation({
    mutationFn: async ({
      id,
      newStart,
      newEnd,
    }: {
      id: string
      newStart: Date
      newEnd: Date
    }) => {
      const durationMs = newEnd.getTime() - newStart.getTime()
      const duration_min = Math.round(durationMs / 60000)
      const res = await fetch(`/api/bookings/${id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          scheduled_at: newStart.toISOString(),
          duration_min,
        }),
      })
      if (!res.ok) {
        const err = await res.json() as { error?: string }
        throw new Error(err.error ?? 'Reschedule failed')
      }
      return res.json()
    },
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: ['bookings'] })
    },
  })

  const handleReschedule = useCallback(
    async (id: string, newStart: Date, newEnd: Date) => {
      await rescheduleMutation.mutateAsync({ id, newStart, newEnd })
    },
    [rescheduleMutation]
  )

  const bookings = data?.data ?? []
  const totalBookings = data?.count ?? 0

  return (
    <div className="flex flex-col flex-1 overflow-hidden h-full">
      <CalendarView
        bookings={bookings}
        isLoading={isLoading}
        error={error ? (error instanceof Error ? error.message : 'Unknown error') : null}
        totalBookings={totalBookings}
        filterArtistIds={filterArtistIds}
        filterStatuses={filterStatuses}
        filterServiceIds={filterServiceIds}
        onArtistFilterChange={(ids) => updateFilters({ artists: ids })}
        onStatusFilterChange={(statuses) => updateFilters({ statuses })}
        onServiceFilterChange={(ids) => updateFilters({ services: ids })}
        onNewAppointment={openNew}
        onEditAppointment={openEdit}
        onReschedule={handleReschedule}
        onRetry={() => {
          void refetch()
        }}
      />

      <AppointmentDrawer
        open={drawerOpen}
        onOpenChange={setDrawerOpen}
        editingId={editingId}
        {...(defaultStart !== undefined ? { defaultStart } : {})}
        {...(defaultEnd !== undefined ? { defaultEnd } : {})}
        onSuccess={() => {
          setDrawerOpen(false)
          void queryClient.invalidateQueries({ queryKey: ['bookings'] })
          toast.success(editingId ? 'Appointment updated' : 'Appointment created')
        }}
      />
    </div>
  )
}

'use client'

import { useState, useCallback } from 'react'

interface CalendarDrawerState {
  drawerOpen: boolean
  setDrawerOpen: (open: boolean) => void
  editingId: string | null
  defaultStart: Date | undefined
  defaultEnd: Date | undefined
  openNew: (start?: Date, end?: Date) => void
  openEdit: (id: string) => void
}

export function useCalendarDrawer(): CalendarDrawerState {
  const [drawerOpen, setDrawerOpen] = useState(false)
  const [editingId, setEditingId] = useState<string | null>(null)
  const [defaultStart, setDefaultStart] = useState<Date | undefined>()
  const [defaultEnd, setDefaultEnd] = useState<Date | undefined>()

  const openNew = useCallback((start?: Date, end?: Date) => {
    setEditingId(null)
    setDefaultStart(start)
    setDefaultEnd(end)
    setDrawerOpen(true)
  }, [])

  const openEdit = useCallback((id: string) => {
    setEditingId(id)
    setDefaultStart(undefined)
    setDefaultEnd(undefined)
    setDrawerOpen(true)
  }, [])

  return {
    drawerOpen,
    setDrawerOpen,
    editingId,
    defaultStart,
    defaultEnd,
    openNew,
    openEdit,
  }
}

