  end: z.string().datetime().optional(),
})

// ── RFC 5545 helpers ──────────────────────────────────────────────────────

function toIcsDate(d: Date): string {
  return d.toISOString().replace(/[-:]/g, '').replace(/\.\d{3}/, '')
}

function escapeIcsText(text: string): string {
  return text
    .replace(/\\/g, '\\\\')
    .replace(/;/g, '\\;')
    .replace(/,/g, '\\,')
    .replace(/\n/g, '\\n')
}

function foldLine(line: string): string {
  if (line.length <= 75) return line
  const parts: string[] = []
  let idx = 0
  while (idx < line.length) {
    parts.push(line.slice(idx, idx + 75))
    idx += 75
  }
  return parts.join('\r\n ')
}

interface BookingRow {
  id: string
  scheduled_at: string
  end_at: string
  status: string
  notes: string | null
  created_at: string
  client: { first_name: string; last_name: string | null; email: string | null } | null
  artist: { display_name: string } | null
  service: { name: string } | null
}

function buildVEvent(booking: BookingRow, studioName: string): string {
  const start = new Date(booking.scheduled_at)
  const end = new Date(booking.end_at)
  const clientName = booking.client
    ? `${booking.client.first_name} ${booking.client.last_name ?? ''}`.trim()
    : 'Unknown Client'
  const summary = [
    booking.service?.name ?? 'Appointment',
    clientName,
  ].join(' — ')
  const description = [
    `Artist: ${booking.artist?.display_name ?? 'Unassigned'}`,
    `Status: ${booking.status}`,
    booking.client?.email ? `Client email: ${booking.client.email}` : null,
    booking.notes ? `Notes: ${booking.notes}` : null,
  ]
    .filter(Boolean)
    .join('\\n')

  const lines = [
    'BEGIN:VEVENT',
    foldLine(`UID:${booking.id}@inkos.app`),
    foldLine(`DTSTAMP:${toIcsDate(new Date(booking.created_at))}`),
    foldLine(`DTSTART:${toIcsDate(start)}`),
    foldLine(`DTEND:${toIcsDate(end)}`),
    foldLine(`SUMMARY:${escapeIcsText(summary)}`),
    foldLine(`DESCRIPTION:${escapeIcsText(description)}`),
    foldLine(`ORGANIZER;CN=${escapeIcsText(studioName)}:mailto:noreply@inkos.app`),
    'END:VEVENT',
  ]

  return lines.join('\r\n')
}

export async function GET(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  const { searchParams } = new URL(request.url)
  const parsed = ExportSchema.safeParse(Object.fromEntries(searchParams))
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })
  }

  const { start, end } = parsed.data
  // studioId from parsed.data is verified against authUser.studioId below —
  // always use the authenticated studio, ignore any passed studioId param
  const studioId = authUser.studioId

  try {
    const supabase = await createClient()

    // Fetch studio name for ORGANIZER
    const { data: studio } = await supabase
      .from('studios')
      .select('name')
      .eq('id', studioId)
      .single()

    const studioName = studio?.name ?? 'InkOS Studio'

    let query = supabase
      .from('bookings')
      .select(
        `id, scheduled_at, end_at, status, notes, created_at,
         client:clients(first_name, last_name, email),
         artist:artists(display_name),
         service:services(name)`
      )
      .eq('studio_id', studioId)
      .not('status', 'in', '("cancelled","no_show")')
      .order('scheduled_at', { ascending: true })

    if (start) query = query.gte('scheduled_at', start)
    if (end) query = query.lte('scheduled_at', end)

    const { data, error: dbError } = await query

    if (dbError) {
      logger.error({ err: dbError }, 'calendar export db error')
      return NextResponse.json({ error: 'Database error' }, { status: 500 })
    }

    const bookings = (data ?? []) as unknown as BookingRow[]

    const vEvents = bookings.map((b) => buildVEvent(b, studioName)).join('\r\n')

    const ics = [
      'BEGIN:VCALENDAR',
      'VERSION:2.0',
      'PRODID:-//InkOS//InkOS Calendar//EN',
      'CALSCALE:GREGORIAN',
      'METHOD:PUBLISH',
      foldLine(`X-WR-CALNAME:${escapeIcsText(studioName)}`),
      'X-WR-TIMEZONE:UTC',
      vEvents,
      'END:VCALENDAR',
    ].join('\r\n')

    const filename = start
      ? `inkos-calendar-${start.slice(0, 10)}.ics`
      : 'inkos-calendar.ics'

    return new NextResponse(ics, {
      status: 200,
      headers: {
        'Content-Type': 'text/calendar; charset=utf-8',
        'Content-Disposition': `attachment; filename="${filename}"`,
        'Cache-Control': 'private, no-cache',
      },
    })
  } catch (err) {
    logger.error({ err }, 'calendar export failed')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

